using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(b =>
        {
            // Breaking change #1: Default discriminator property renamed from
            // "Discriminator" to "$type" in EF Core 9. Existing documents use
            // "Discriminator", so pin the old name explicitly.
            b.HasDiscriminator<string>("Discriminator");

            // Breaking change #2: Default id format changed from
            // "{Discriminator}|{Key}" to just "{Key}" in EF Core 9. Existing
            // documents have ids like "Blog|1", so restore the old format.
            b.Property<string>("__id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();

            // Breaking change #3: HasIndex() now throws on the Cosmos provider.
            // Removed the previous HasIndex(b => b.Name) call — Cosmos uses
            // indexing policies configured at the container level, not EF indexes.
        });
    }
}

/// <summary>
/// Reproduces the EF Core 8 Cosmos id format: "{Discriminator}|{Key}".
/// Ensures new documents remain compatible with existing data.
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var discriminator = entry.Metadata.GetDiscriminatorValue()?.ToString()
            ?? entry.Metadata.ShortName();
        var key = entry.Property(entry.Metadata.FindPrimaryKey()!.Properties[0].Name)
            .CurrentValue?.ToString();
        return $"{discriminator}|{key}";
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

